.timeline-controls{position:relative;background:var(--color-neutral-background-bold);padding:4px}.timeline-controls__buffering{left:0;right:0;top:0;height:4px;position:absolute;background-color:var(--color-primary-content);overflow:hidden}.timeline-controls__buffering::after{content:"";position:absolute;top:0;left:-100%;width:25%;height:100%;will-change:left;background-color:var(--color-primary-content-subtle);animation:buffering-media 800ms ease-out infinite}.timeline-controls__counter{height:36px;min-width:115px;display:flex;align-items:center;justify-content:center;background:var(--color-neutral-surface);border-radius:var(--corner-radius-smaller);font-weight:500;font-size:16px;line-height:19px;color:var(--color-neutral-content);padding:0 8px}.timeline-controls__counter span{opacity:.4;padding-left:5px;font-weight:400}.timeline-controls__counter input{width:100%;height:100%;border:none;background:none;padding:0;margin:0;font-size:16px;line-height:19px;text-align:center}.timeline-controls__main-controls{display:flex;max-width:310px;justify-content:space-between;gap:var(--spacing-tight)}.timeline-controls__group{gap:4px}.timeline-controls .button{background:none;width:36px;height:36px;color:var(--color-neutral-content);border:1px solid rgba(0,0,0,0);cursor:pointer}.timeline-controls .button:hover{border:1px solid var(--color-neutral-border)}.timeline-controls .button:disabled{opacity:.3}.timeline-controls__time{height:36px;display:flex;font-size:16px;border-radius:4px;color:var(--color-neutral-content-subtler);border:1px solid var(--color-neutral-border)}.timeline-controls__time-section{display:flex;height:100%;padding:0 8px;align-items:center}.timeline-controls__time-section span{opacity:.48}.timeline-controls__time-section span::before{content:":"}.timeline-controls__time-section+.timeline-controls__time-section{border-left:1px solid var(--color-neutral-border)}.timeline-time{padding:0 5px;font-size:16px;display:inline-flex;align-items:center;color:var(--color-neutral-content-subtler)}.timeline-time span{font-size:11px;min-width:22px;border-radius:2px;text-align:center;margin-left:5px;display:inline-block;color:var(--color-neutral-content-subtle);background:var(--color-neutral-surface)}@keyframes buffering-media{0%{left:-100%}100%{left:100%}}