.topbar{height:var(--topbar-height);width:100%;z-index:101;flex:none;display:flex;align-items:stretch;justify-content:space-between;background-color:var(--color-neutral-surface);border-bottom:1px solid var(--color-neutral-border);user-select:none;position:sticky;top:0}.topbar__button{transform:translateX(var(--spacing-tighter))}.topbar__group{display:flex;align-items:stretch;gap:var(--spacing-tight);padding-left:var(--spacing-tight);overflow:hidden}.topbar__section{display:flex;padding:0 8px;align-items:center;box-sizing:border-box}.topbar__section_flat{padding:0}.topbar__section+.topbar__section{border-left:1px solid var(--color-neutral-border)}.topbar_newLabelingUI{display:block;background-color:var(--color-neutral-surface);height:42px;border-bottom:1px solid var(--color-neutral-border)}.topbar_newLabelingUI .topbar__group{height:42px;flex:1;align-items:center}