.auto-accept{height:44px;display:flex;align-items:center;box-sizing:border-box;background-color:var(--color-neutral-background);margin-left:var(--spacing-tight)}.auto-accept__wrapper{width:100%}.auto-accept__wrapper_loading{opacity:.5}.auto-accept__info{font-size:16px}.auto-accept__action{margin:2px;width:28px;height:28px;display:flex;align-items:center;justify-content:center;border-radius:100%;background-color:var(--color-neutral-surface);padding:var(--spacing-tightest);transition:all 150ms ease-out}.auto-accept__action_type_accept{border:1px solid var(--color-positive-border);background-color:var(--color-positive-surface);color:var(--color-positive-surface-content)}.auto-accept__action_type_accept:hover{background-color:var(--color-positive-surface-hover)}.auto-accept__action_type_accept svg{width:20px;height:20px}.auto-accept__action_type_reject{border:1px solid var(--color-negative-border);background-color:var(--color-negative-surface);color:var(--color-negative-surface-content)}.auto-accept__action_type_reject:hover{background-color:var(--color-negative-surface-hover)}.auto-accept__action_type_reject svg{width:20px;height:20px}.auto-accept__spinner{width:16px;height:16px;border-radius:100%;box-sizing:border-box;border:2px solid var(--persimmon_400);border-right-color:rgba(0,0,0,0);animation:waiting-spin 1s linear infinite}@keyframes waiting-spin{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}