.annotations-carousel{--carousel-left: 0;position:relative;height:100%;align-items:center;min-width:0;flex:1}.annotations-carousel::before{content:"";position:absolute;top:0;left:0;width:8px;height:100%;display:block;pointer-events:none;opacity:0;background:linear-gradient(to right, rgba(var(--color-neutral-shadow-raw)/16%), rgba(var(--color-neutral-shadow-raw)/0%));z-index:1;transition:opacity 300ms ease-out}.annotations-carousel_scrolled::before{opacity:1}.annotations-carousel_virtualized .annotations-carousel__container{overflow:visible}.annotations-carousel__container{display:flex;width:100%;justify-content:space-between;overflow:hidden;height:100%}.annotations-carousel__carosel{flex:1;display:flex;gap:var(--spacing-tighter);white-space:nowrap;padding-left:var(--spacing-tighter);padding-right:77px;position:relative;transform:translateX(calc(-1 * var(--carousel-left)));transition:all 200ms ease-out 0s}.annotations-carousel__carousel-controls{position:absolute;right:0;white-space:nowrap;top:50%;transform:translateY(-50%);display:flex;gap:var(--spacing-tighter);padding-right:var(--spacing-tighter)}.annotations-carousel__carousel-controls button:not(:disabled){box-shadow:0 2px 6px rgba(var(--color-neutral-shadow-raw)/20%)}.annotations-carousel__nav{padding:0;height:28px;width:28px;box-shadow:0 2px 5px 0 rgb(var(--color-neutral-shadow-raw)/20%)}.annotations-carousel__nav:hover{background:var(--color-primary-emphasis-subtle);box-shadow:0 2px 5px 0 rgb(var(--color-neutral-shadow-raw)/20%)}.annotations-carousel__nav_disabled{background:var(--color-background-surface)}.annotations-carousel__nav_disabled svg{opacity:.4}.annotations-carousel__nav_disabled:hover{background:var(--color-neutral-surface);filter:none}.annotations-carousel__nav .button:hover{filter:none}.annotations-carousel__nav .button__arrow_left{transform:rotate(-90deg)}.annotations-carousel__nav .button__arrow_right{transform:rotate(90deg)}